import unittest

from solucao import unicos
from solucao import dupla_de_conjuntos


class TestConjuntoSemRepetidos(unittest.TestCase):
    def test_unicos_tira_as_repeticoes(self):
        """unicos elimina os numeros repetidos"""
        self.assertEqual(len(unicos([1, 1, 2])), 2)

    def test_unicos_sem_repeticoes(self):
        """unicos so com numeros sozinhos devolve os mesmos numeros"""
        self.assertEqual(sorted(unicos([7, 7])), [7])

    def test_unicos_da_lista_vazia(self):
        """unicos da lista vazia devolve o conjunto vazio"""
        self.assertEqual(len(unicos([])), 0)

    def test_dupla_de_conjuntos_tem_dois_conjuntos(self):
        """dupla_de_conjuntos devolve a lista com os conjuntos {1} e {2}"""
        self.assertEqual(str(dupla_de_conjuntos()), "[{1}, {2}]")

solutionCode:
def unicos(numeros):
    return set(numeros)


def dupla_de_conjuntos():
    return [{1}, {2}]
